template.script:
(function () {

  // ======= GALERÍA (nuevo producto) =======
  function initNewGallery(){
    const addBtn = document.getElementById("np_add_btn");
    const addInput = document.getElementById("np_add_input");
    const thumbs = document.getElementById("np_thumbs");

    const mainImg = document.getElementById("np_main_img");
    const placeholder = document.getElementById("np_main_placeholder");

    const prevBtn = document.getElementById("np_prev_btn");
    const nextBtn = document.getElementById("np_next_btn");

    if (!addBtn || !addInput || !thumbs || !mainImg || !placeholder) return;

    function getThumbImgs(){
      return Array.from(thumbs.querySelectorAll("img.np-thumb"));
    }

    function reindex(){
      getThumbImgs().forEach((img, idx) => img.dataset.index = String(idx));
    }

    function showArrowsIfNeeded(){
      const n = getThumbImgs().length;
      if (!prevBtn || !nextBtn) return;
      const show = n > 1;
      prevBtn.style.display = show ? "flex" : "none";
      nextBtn.style.display = show ? "flex" : "none";
    }

function setActive(idx){
  const list = getThumbImgs();
  const t = list[idx];
  if (!t) return;

  // ✅ poner imagen en main
  mainImg.src = t.dataset.url;
  mainImg.dataset.index = String(idx);

  // ✅ mostrar img / ocultar placeholder SIEMPRE

  placeholder.style.setProperty("display", "none", "important");
        mainImg.style.setProperty("display", "block", "important");


  list.forEach((el, i) => {
    if (i === idx) {
      el.style.border = "2px solid rgba(18,62,92,.55)";
      el.style.boxShadow = "0 8px 18px rgba(18,62,92,.15)";
    } else {
      el.style.border = "1px solid rgba(0,0,0,.12)";
      el.style.boxShadow = "none";
    }
  });

  showArrowsIfNeeded();
}


 function go(delta) {
      const thumbs = getThumbImgs();
      const n = thumbs.length;
      if (!n) return;

      // si main es div "Sin fotos", no hay navegación
      if (!mainImg.tagName || mainImg.tagName.toLowerCase() !== "img") return;

      const current = parseInt((mainImg.dataset && mainImg.dataset.index) || "0", 10);
      const next = (current + delta + n) % n;
      setActive(next);
    }

    if (prevBtn) prevBtn.addEventListener("click", () => go(-1));
    if (nextBtn) nextBtn.addEventListener("click", () => go(1));

    addBtn.addEventListener("click", () => addInput.click());

    addInput.addEventListener("change", () => {
      const files = Array.from(addInput.files || []);
      if (!files.length) return;

      // Insertar thumbs antes del botón +
      const beforeNode = addBtn;

      files.forEach((f) => {
        if (!f.type || !f.type.startsWith("image/")) return;
        const url = URL.createObjectURL(f);

        const img = document.createElement("img");
        img.className = "np-thumb";
        img.dataset.url = url;
        img.alt = "Miniatura";
        img.src = url;

        thumbs.insertBefore(img, beforeNode);
      });

      reindex();

      // activar la primera si no había ninguna
      const list = getThumbImgs();
      if (list.length) setActive(0);
    });

    // click miniaturas
    thumbs.addEventListener("click", (e) => {
      const t = e.target.closest("img.np-thumb");
      if (!t) return;
      const idx = parseInt(t.dataset.index || "0", 10);
      setActive(idx);
    });
  }

  // ======= CERTIFICADOS (tu código intacto) =======
  let prodCertIndex = 0;
  let prodCertCache = null;

  async function fetchProductCerts() {
    if (prodCertCache) return prodCertCache;

    const payload = { jsonrpc: "2.0", method: "call", params: {}, id: Date.now() };
    const r = await fetch("/marketplace/certificados_producto", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      credentials: "same-origin",
    });

    const data = await r.json();
    if (data.error) throw new Error(data.error.data?.message || data.error.message || "Error RPC");
    prodCertCache = data.result || [];
    return prodCertCache;
  }

  function buildOptions(certs) {
    const out = ['<option value="">Seleccione…</option>'];
    certs.forEach(c => {
      const issuer = (c.issuer || "").replace(/"/g, "&quot;");
      out.push(`<option value="${c.id}" data-issuer="${issuer}">${c.name}</option>`);
    });
    return out.join("");
  }

  function rowHtml(idx, optionsHtml) {
    return `
      <div class="card border-0 mb-3 mp-cert-row">
        <div class="card-body p-3">
          <div class="d-flex justify-content-between align-items-center mb-3">
            <div style="font-weight:800;"><i class="fa fa-certificate me-1" style="color:var(--shrimp-teal);"></i> Nuevo certificado</div>
            <button type="button" class="s-btn s-btn-danger btn-sm delBtn"><i class="fa fa-trash-o me-1"></i> Eliminar</button>
          </div>

          <div class="row g-3">
            <div class="col-md-5">
              <label class="form-label" style="font-weight:800; font-size:13px;">Certificado</label>
              <select class="form-select certSel" name="prod_cert_${idx}_id" required>
                ${optionsHtml}
              </select>
            </div>

            <div class="col-md-3">
              <label class="form-label" style="font-weight:800; font-size:13px;">Entidad</label>
              <input class="form-control issuer" type="text" readonly placeholder="Entidad"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">N°</label>
              <input class="form-control" name="prod_cert_${idx}_number" placeholder="Opcional"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Emisión</label>
              <input class="form-control" type="date" name="prod_cert_${idx}_issue_date"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Expira</label>
              <input class="form-control" type="date" name="prod_cert_${idx}_expiry_date"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Archivo <span class="text-danger">*</span></label>
              <input class="form-control" type="file" name="prod_cert_${idx}_file" required accept="image/*,application/pdf"/>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  async function addRow() {
    const container = document.getElementById("prodCertContainer");
    if (!container) return;

    const certs = await fetchProductCerts();
    const idx = prodCertIndex++;

    const wrapper = document.createElement("div");
    wrapper.innerHTML = rowHtml(idx, buildOptions(certs));
    const card = wrapper.firstElementChild;
    // Los nuevos certificados se agregan al inicio de la lista.
    container.insertBefore(card, container.firstChild);

    const sel = card.querySelector(".certSel");
    const issuerInp = card.querySelector(".issuer");

    sel.addEventListener("change", () => {
      const opt = sel.selectedOptions[0];
      issuerInp.value = opt ? (opt.getAttribute("data-issuer") || "") : "";
    });

    card.querySelector(".delBtn").addEventListener("click", () => card.remove());
  }

  function initCerts() {
    const btn = document.querySelector(".shrimpAddProdCert");
    if (!btn) return;

    btn.addEventListener("click", () => addRow());

    // inicia con 1 fila
     // addRow();
  }

  function initPondFilter(){
    var fac = document.getElementById("originFacility");
    var pond = document.getElementById("originPond");
    if(!fac || !pond) return;
    var opts = Array.prototype.slice.call(pond.querySelectorAll("option[value]")).filter(function(o){ return o.value; });
    function apply(){
      var f = fac.value;
      var currentOk = false;
      opts.forEach(function(o){
        var of = o.getAttribute("data-facility") || "";
        // Muestra piscinas de la instalación elegida; si no hay instalación, muéstralas todas.
        var show = !f || of === f;
        o.hidden = !show;
        o.disabled = !show;
        if(show && o.selected) currentOk = true;
      });
      if(!currentOk){ pond.value = ""; }
    }
    fac.addEventListener("change", apply);
    apply();
  }

  function initProdCertDelete(){
    document.querySelectorAll(".prod-cert-del-btn").forEach(function(btn){
      btn.addEventListener("click", function(){
        var card = btn.closest(".prod-cert-card");
        if(!card) return;
        var flag = card.querySelector(".prod-cert-del-flag");
        if(flag){ flag.checked = true; }
        card.style.display = "none";
      });
    });
  }

  function initSizeFilter(){
    var pres = document.getElementById("prodPresentation");
    var size = document.getElementById("prodSizeGrade");
    if(!pres || !size) return;
    var opts = Array.prototype.slice.call(size.querySelectorAll("option[value]")).filter(function(o){ return o.value; });
    function apply(){
      var p = pres.value;
      var ok = false;
      opts.forEach(function(o){
        var op = o.getAttribute("data-presentation") || "";
        var show = !!p && op === p;   // sin presentación no hay tallas válidas
        o.hidden = !show; o.disabled = !show;
        if(show && o.selected) ok = true;
      });
      if(!ok){ size.value = ""; }
    }
    pres.addEventListener("change", apply);
    apply();
  }

  function init(){
    initNewGallery();
    initCerts();
    initPondFilter();
    initProdCertDelete();
    initSizeFilter();
  }

  document.addEventListener("DOMContentLoaded", init);

})();

(function () {
function initMarketplaceGallery() {
const mainImg = document.getElementById("mp_main_img");
const thumbsWrap = document.getElementById("mp_thumbs");
const prevBtn = document.getElementById("mp_prev_btn");
const nextBtn = document.getElementById("mp_next_btn");

if (!mainImg || !thumbsWrap) return;

function getThumbs() {
return Array.from(thumbsWrap.querySelectorAll(".mp-thumb"));
}

function setActive(idx) {
const thumbs = getThumbs();
const t = thumbs[idx];
if (!t) return;

mainImg.src = t.dataset.url;
mainImg.dataset.index = String(idx);

thumbs.forEach((el, i) => {
if (i === idx) {
el.style.border = "2px solid rgba(18,62,92,.55)";
el.style.boxShadow = "0 8px 18px rgba(18,62,92,.15)";
} else {
el.style.border = "1px solid rgba(0,0,0,.12)";
el.style.boxShadow = "none";
}
});
}

thumbsWrap.addEventListener("click", function (e) {
const thumb = e.target.closest(".mp-thumb");
if (!thumb) return;

const idx = parseInt(thumb.dataset.index || "0", 10);
setActive(idx);
});

function go(delta) {
const thumbs = getThumbs();
const n = thumbs.length;
if (!n) return;

const current = parseInt(mainImg.dataset.index || "0", 10);
const next = (current + delta + n) % n;
setActive(next);
}

if (prevBtn) prevBtn.addEventListener("click", () => go(-1));
if (nextBtn) nextBtn.addEventListener("click", () => go(1));

setActive(0);
}

if (document.readyState === "loading") {
document.addEventListener("DOMContentLoaded", initMarketplaceGallery);
} else {
initMarketplaceGallery();
}
})();
